static int emit(P2D89_ShapeId id,const P2D89_Provider *p){static const p2d89_q14 plane[]={2048,-12288,12288,-12288,12288,-2048,2048,-2048};if(id==P2D89_SHAPE_GIZMO_MOVE_X)return arrowx(p);if(id==P2D89_SHAPE_GIZMO_MOVE_Y)return arrowy(p);if(id==P2D89_SHAPE_GIZMO_MOVE_XY){if(!arrowx(p))return 0;return arrowy(p);}if(id==P2D89_SHAPE_GIZMO_SCALE_X){if(!l(-12288,0,12288,0,p))return 0;return square_at(14336,0,p);}if(id==P2D89_SHAPE_GIZMO_SCALE_Y){if(!l(0,12288,0,-12288,p))return 0;return square_at(0,-14336,p);}if(id==P2D89_SHAPE_GIZMO_SCALE_XY){if(!l(0,0,10240,-10240,p))return 0;return square_at(12288,-12288,p);}if(id==P2D89_SHAPE_GIZMO_ROTATE){if(!p2d89_i_arc_3q(p))return 0;if(!l(0,-16384,4096,-12288,p))return 0;return l(0,-16384,-2048,-10240,p);}if(id==P2D89_SHAPE_GIZMO_PIVOT){if(!p2d89_emit_ellipse(8192,8192,1,p))return 0;return p2d89_emit_ellipse(3072,3072,0,p);}if(id==P2D89_SHAPE_GIZMO_ORIGIN_AXES){if(!arrowx(p))return 0;if(!arrowy(p))return 0;return p2d89_i_point(p,0,0);}if(id==P2D89_SHAPE_GIZMO_PLANE_XY){if(!arrowx(p))return 0;if(!arrowy(p))return 0;return p2d89_i_poly(plane,4U,1,p);}if(id==P2D89_SHAPE_GIZMO_AXIS_HANDLE){if(!l(-12288,0,8192,0,p))return 0;return square_at(12288,0,p);}if(id==P2D89_SHAPE_GIZMO_ROTATION_ARC){if(!p2d89_i_move(p,14336,0))return 0;if(!p2d89_i_cubic(p,14336,-8192,8192,-14336,0,-14336))return 0;if(!p2d89_i_cubic(p,-8192,-14336,-14336,-8192,-14336,0))return 0;if(!l(-14336,0,-10240,-4096,p))return 0;return l(-14336,0,-8192,2048,p);}return 0;}
